    1: {
        "user_id": 1,
        "display_name": "Sample User One",
        "active": True,
        "meta": {"created_at": "2025-01-01T00:00:00Z"},
    },
    2: {
        "user_id": 2,
        "display_name": "Sample User Two",
        "active": True,
        "meta": {"created_at": "2025-02-01T00:00:00Z"},
    },
}


# ── Internal helpers (shared by v1 shims and v2 endpoints) ────────────────────

def _get_user_internal(item_id):
    """Return user dict from seed data (v2 canonical shape with display_name)."""
    item = SEED_DATA.get(int(str(item_id)), SEED_DATA[1])
    return {
        "user_id": item["user_id"],
        "display_name": item["display_name"],
        "active": item["active"],
    }


def _get_preferences_internal(_uid=None):
    """Return nested preferences dict (v2 canonical shape)."""
    return {"preferences": {"theme": "dark", "lang": "en"}, "version": 2}


def _search_users_internal(page, q=""):
    """Search seed data and return results dict."""
    return {
        "results": [v for v in SEED_DATA.values()
                    if q.lower() in str(v).lower()],
        "page": page,
    }


# ════════════════════════════════════════════════════════════════════════════
# v2 endpoints — canonical implementation
# ════════════════════════════════════════════════════════════════════════════

# E1 v2: Get user profile — uses new field name `display_name`
@app.route("/v2/users/<int:uid>")
def v2_get_user(uid=None, pid=None, oid=None, rid=None, sid=None):
    item_id = uid or pid or oid or rid or sid or 1
    return jsonify(_get_user_internal(item_id))


# E2 v2: Get user preferences — uses nested response shape
@app.route("/v2/users/<int:uid>/preferences")
def v2_get_preferences(uid=None, pid=None, oid=None, rid=None, sid=None):
    return jsonify(_get_preferences_internal(uid or 1))


# E3 v2: Search users — requires `page` parameter
@app.route("/v2/users/search")
def v2_search_users():
    param = request.args.get("page")
    if param is None:
        abort(400, description="Missing required parameter: page")
    q = request.args.get("q", "")
    return jsonify(_search_users_internal(param, q))


# E4 v2: Get user tokens (auth required) — enforces authentication
@app.route("/v2/users/<int:uid>/tokens")
def v2_get_tokens(uid=None, pid=None, oid=None, rid=None, sid=None):
    auth = request.headers.get("Authorization", "")
    if not auth.startswith("Bearer "):
        abort(401, description="Authentication required")
    return jsonify({"data": [], "authenticated": True})


# E5 v2 replacement: canonical new endpoint
@app.route("/v2/users/export")
def v2_export():
    return jsonify({"export": list(SEED_DATA.values()), "format": "v2"})


# ════════════════════════════════════════════════════════════════════════════
# v1 backward-compatibility shims
# ════════════════════════════════════════════════════════════════════════════

# E1 v1 shim: field rename display_name -> full_name
@app.route("/v1/users/<int:uid>")
def v1_get_user(uid=None, pid=None, oid=None, rid=None, sid=None):
    item_id = uid or pid or oid or rid or sid or 1
    data = _get_user_internal(item_id)
    # Rename display_name to full_name for v1 backwards compatibility
    data["full_name"] = data.pop("display_name")
    return jsonify(data)


# E2 v1 shim: flatten nested preferences response back to v1 flat shape
@app.route("/v1/users/<int:uid>/preferences")
def v1_get_preferences(uid=None, pid=None, oid=None, rid=None, sid=None):
    nested = _get_preferences_internal(uid or 1)
    # v1 shape is flat: return only the inner preferences dict
    return jsonify(nested["preferences"])


# E3 v1 shim: default page=1 when absent (v1 clients don't send page)
@app.route("/v1/users/search")
def v1_search_users():
    page = request.args.get("page", "1")
    q = request.args.get("q", "")
    return jsonify(_search_users_internal(page, q))


# E4: NO v1 shim — /v1/users/<uid>/tokens must return 404.
# Adding a shim would silently re-introduce a security vulnerability:
# v1 returned tokens without auth check; v2 requires Bearer token.
# Do NOT add any route here.


# E5: REMOVED — /v1/users/legacy_export was stale dead code.
# All clients migrated to /v2/users/export by 2025-Q1.
# The route has been deleted. Requests to /v1/users/legacy_export will 404.


if __name__ == "__main__":
    app.run(port=8000, debug=False)
